INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 36, 'theory', 'Quiz: tokio — networking and I/O');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 0, 'What does it mean when read() returns 0?', '["There is no data yet", "The peer closed the connection: end of stream", "An error occurred", "The buffer is empty"]', 1, 'Zero bytes is the sign of the end of the stream (EOF). The absence of data is expressed by waiting, not by zero.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 1, 'Why can''t a single read() be guaranteed to get a whole message?', '["The buffer size is limited to 1 byte", "TCP is a stream of bytes with no message boundaries: data may arrive in pieces", "read works only in blocking mode", "A socket always reads one byte at a time"]', 1, 'Message boundaries are not preserved in TCP: you need a length prefix or a delimiter, or read_exact for a known length.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 2, 'What is into_split() for?', '["Splitting a file into parts", "Getting owned reading and writing halves of a socket to give to different tasks", "Creating two connections", "Compressing data"]', 1, 'into_split returns OwnedReadHalf and OwnedWriteHalf; they can be moved into different tasks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 3, 'How do you tell the peer "I am done sending" but keep reading the reply?', '["Drop the whole socket", "Call shutdown() on the writing half", "Send an empty message", "Close the program"]', 1, 'shutdown closes only the writing side: the peer gets EOF, and the reading half stays open.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 4, 'How does UdpSocket differ from TcpStream?', '["It doesn''t", "No connection: separate datagrams with boundaries preserved, no guarantees of delivery and order", "UDP is more reliable than TCP", "UDP works only within one machine"]', 1, 'UDP carries independent datagrams: boundaries are preserved, but loss, repeats and reordering are possible.');
